import { SITE_URL } from "./contact";

/* Without per-route og:* tags every shared link renders with the homepage's title
   and description. This also emits a canonical, since the same page is reachable
   in either site mode. */
export function pageMeta({
	title,
	description,
	path,
	image = "/og-image.png",
	noindex = false,
}: {
	title: string;
	description: string;
	path: string;
	/* per-route share card from public/og/, generated by scripts/generate-og-images.ts */
	image?: string;
	/* keeps a reachable page out of search results. Deliberately a meta tag rather
	   than a robots.txt Disallow: a disallowed URL can still be indexed from a
	   link elsewhere, because the crawler is barred from fetching the page and so
	   never sees the instruction not to index it. */
	noindex?: boolean;
}) {
	const url = `${SITE_URL}${path}`;
	return {
		meta: [
			{ title },
			{ name: "description", content: description },
			{ property: "og:title", content: title },
			{ property: "og:description", content: description },
			{ property: "og:url", content: url },
			{ property: "og:image", content: `${SITE_URL}${image}` },
			{ name: "twitter:image", content: `${SITE_URL}${image}` },
			...(noindex ? [{ name: "robots", content: "noindex, nofollow" }] : []),
		],
		links: [{ rel: "canonical", href: url }],
	};
}
